scores = queryNew("name,score", "varchar,integer");
queryAddRow(scores, {name: "Alice", score: 90});
queryAddRow(scores, {name: "Bob", score: 75});
Spreadsheet("xlsx")
	.sheet("Data")
	.fromQuery(scores, true)
	.addChart({
		type: "bar",
		series: ["Data!$B$2:$B$3"],
		from: "E1",
		to: "L15",
		title: "Scores"
	})
	.write(expandPath("/chart.xlsx"), true);
